1	// The player: a medieval mage in first person (GDD 0, 3, 9).
2	#pragma once
3	
4	#include "CoreMinimal.h"
5	#include "GameFramework/Character.h"
6	#include "Core/GBTypes.h"
7	#include "QTE/GBQTELogic.h"
8	#include "GBPlayerCharacter.generated.h"
9	
10	class UCameraComponent;
11	class UGBStatsComponent;
12	class UGBAttributeComponent;
13	class UGBStatusEffectComponent;
14	class UGBEquipmentComponent;
15	class UGBSpellbookComponent;
16	class UGBQTEComponent;
17	class UGBInventoryComponent;
18	class UGBSkillTreeComponent;
19	class UGBInputSet;
20	class IGBInteractable;
21	class UDamageType;
22	struct FInputActionValue;
23	struct FGBPlayerSnapshot;
24	struct FGBDamageInfo;
25	
26	/**
27	 * Owns the components that make up the player and routes input to them. It holds no gameplay numbers:
28	 * movement reads the stats (MoveSpeed, JumpVelocity, MaxJumps, AirControl, GravityScale, DashDistance,
29	 * DashDuration, DashCooldown, InteractRange) from UGBStatsComponent and re-reads them on OnStatsChanged,
30	 * so air passives, armor and slows work by adding modifiers.
31	 *
32	 * Movement (GDD 9): walk, jump, double jump (MaxJumps), dash (Ctrl / Circle) in the movement direction, no sprint.
33	 * During the spell QTE: the camera is locked, W/A/S/D and the mouse go to the QTE, and the player keeps moving
34	 * in the direction it was moving (the last movement input is held).
35	 *
36	 * Jumps commit to their direction (GDD 18): OnJumped sets the horizontal velocity from the movement input held
37	 * at takeoff (AirControl stays 0, so the air applies no steering). The dash is the only steering in the air.
38	 */
39	UCLASS()
40	class GLYPHBOUND_API AGBPlayerCharacter : public ACharacter
41	{
42		GENERATED_BODY()
43	
44	public:
45		AGBPlayerCharacter();
46	
47		/** The local player character, or null. */
48		static AGBPlayerCharacter* Get(const UObject* WorldContextObject);
49	
50		// ---- Components ----
51		UCameraComponent* GetCamera() const { return Camera; }
52		UGBStatsComponent* GetStats() const { return Stats; }
53		UGBAttributeComponent* GetAttributes() const { return Attributes; }
54		UGBStatusEffectComponent* GetStatusEffects() const { return StatusEffects; }
55		UGBEquipmentComponent* GetEquipment() const { return Equipment; }
56		UGBSpellbookComponent* GetSpellbook() const { return Spellbook; }
57		UGBQTEComponent* GetQTE() const { return QTE; }
58		UGBInventoryComponent* GetInventory() const { return Inventory; }
59		UGBSkillTreeComponent* GetSkillTree() const { return SkillTree; }
60	
61		/** Held items attach here: a scene component under the camera (right-hand side of the view). */
62		USceneComponent* GetHeldItemAnchor() const { return HeldItemAnchor; }
63	
64		// ---- Aiming ----
65		/** Camera location and forward vector: where shots and spells start and point. */
66		FVector GetAimOrigin() const;
67		FVector GetAimDirection() const;
68		/** A point a little in front of the right hand, for projectiles that should not start inside the camera. */
69		FVector GetMuzzleLocation() const;
70		/** Kicks the view (degrees). It recovers on its own at RecoverPerSecond. */
71		void AddRecoil(float Pitch, float Yaw, float RecoverPerSecond);
72		/**
73		 * View-only shake of the first-person camera (GDD 18): offsets the camera component's relative
74		 * rotation with a decaying shake for Duration seconds, then returns it exactly to zero. The aim
75		 * (control rotation) does not move. Calling it again while shaking restarts with the stronger amplitude.
76		 */
77		void StartViewShake(float Duration, float AmplitudeDeg, float Frequency);
78		/**
79		 * True while the input action of the loadout slot holding SpellId is currently held
80		 * (slot 1 = right click / L1, slots 2-5 = keys 1-4, gamepad L2 + face button).
81		 * A caster that is not this player, or a spell that is not in the loadout, counts as
82		 * held (then a sustained spell only ends by mana, death, switch or its duration rules).
83		 */
84		bool IsSpellInputHeld(FName SpellId) const;
85	
86		// ---- Movement state ----
87		bool IsDashing() const { return bDashing; }
88		/** Seconds until the dash is ready again; 0 when ready. */
89		float GetDashCooldownRemaining() const;
90		/** Multiplies walk speed while set (aiming down sights). 1 = normal. */
91		void SetMoveSpeedScale(float Scale);
92	
93		// ---- Interaction ----
94		/** The interactable the player is looking at and can use right now, or null. The HUD shows its prompt. */
95		IGBInteractable* GetFocusedInteractable() const;
96		AActor* GetFocusedInteractableActor() const { return FocusedInteractable.Get(); }
97	
98		// ---- State ----
99		bool IsDead() const;
100		/** Restores health, mana and ammo (respawn and era travel, GDD 4). Fractions of the maximums (1 = full); bOnlyRaise raises health/mana towards them without lowering. */
101		void RestoreAll(float HealthFraction = 1.f, float ManaFraction = 1.f, bool bRefillAmmo = true, bool bOnlyRaise = false);
102		/** Stops input-driven actions and hides the held item (death, cutscene). */
103		void SetControlEnabled(bool bEnabled);
104		bool IsControlEnabled() const { return bControlEnabled; }
105		/** Releases everything held down (fire, aim, held movement). Called when a menu opens or control is lost. */
106		void ReleaseHeldInputs();
107	
108		/** Whole-player snapshot: transform, era, attributes, plus every component's part. */
109		void SaveToSnapshot(FGBPlayerSnapshot& Snapshot) const;
110		void LoadFromSnapshot(const FGBPlayerSnapshot& Snapshot);
111		/**
112		 * Death respawn at the checkpoint's place and era with full health, mana and ammo. Everything else
113		 * owned (items, weapons, spells, skill points, armor) is kept as it is now: dying never rolls it back.
114		 */
115		void RespawnAt(const FGBPlayerSnapshot& Snapshot);
116	
117		virtual void Tick(float DeltaSeconds) override;
118		virtual void SetupPlayerInputComponent(UInputComponent* PlayerInputComponent) override;
119		/**
120		 * Below the world's KillZ (set by AGBGameMode from Game.json "KillZ"): the pawn is never destroyed. It is killed
121		 * through its attributes (even if invulnerable), so the normal death screen and checkpoint respawn run, and
122		 * the fall stops until RespawnAt. Called every frame while below KillZ; only the first call kills.
123		 */
124		virtual void FellOutOfWorld(const UDamageType& DmgType) override;
125	
126		/**
127		 * Committed jump takeoff (GDD 18): inside OnJumped, JumpCurrentCount is 1 for a jump from the ground and
128		 * 2+ for a jump that starts in the air (the double jump, or the first jump after walking off a ledge:
129		 * CheckJumpInput pre-increments the count to 1 while falling, then the successful jump increments it to 2).
130		 */
131		virtual void OnJumped_Implementation() override;
132	
133		/**
134		 * Horizontal velocity a committed jump takes off with (pure, tested).
135		 * InputDirection is the world-space movement direction held at takeoff (zero when none).
136		 * No input: returns CurrentVelocity unchanged (the jump keeps its drift). With input: the input direction
137		 * at max(CurrentSpeed, MaxWalkSpeed * MinSpeedMult).
138		 */
139		static FVector2D ComputeJumpHorizontalVelocity(const FVector2D& CurrentVelocity, const FVector2D& InputDirection, float MaxWalkSpeed, float MinSpeedMult);
140	
141	protected:
142		virtual void BeginPlay() override;
143		virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;
144	
145		/** Reads the movement stats into the character movement component. Bound to OnStatsChanged. */
146		void ApplyMovementStats();
147		void HandleDeath(const FGBDamageInfo& KillingBlow);
148		/**
149		 * Precision Recovery (GDD 18): bound to UGBCombatLibrary::OnDamageDealt. When anything dies from a
150		 * weak point killing blow by this player and the perk's cooldown is over, heals the perk's fraction
151		 * of max health. Once per death by construction: only a blow that really removed health fires the event.
152		 */
153		void HandlePrecisionRecovery(AActor* Target, const FGBDamageInfo& Info, float DamageDealt);
154		void UpdateFocusedInteractable();
155		void HandleDataReloaded();
156	
157		/** Stat with modifiers; warns once if the base value is missing from Player.json. */
158		float ReadStat(FName Stat, float DefaultValue) const;
159		bool CanUseGameplayInput() const;
160		bool IsQTEActive() const;
161		/** World-space horizontal direction of a 2D movement input (x = right, y = forward) relative to the view yaw. Zero when there is no input. */
162		FVector GetMoveInputWorldDirection(const FVector2D& Input) const;
163		/** Movement input (x = right, y = forward) relative to the view yaw. */
164		void ApplyMoveInput(const FVector2D& Input);
165		/** Turns the view (degrees). Positive pitch looks up. */
166		void AddLookDelta(float YawDegrees, float PitchDegrees);
167		void UpdateWalkSpeed();
168		void EndDash();
169		void TickRecoil(float DeltaSeconds);
170		void TickViewShake(float DeltaSeconds);
171	
172		// Input handlers (bound to the actions of UGBInputSet)
173		void InputMove(const FInputActionValue& Value);
174		void InputMoveCompleted(const FInputActionValue& Value);
175		void InputLook(const FInputActionValue& Value);
176		void InputLookStick(const FInputActionValue& Value);
177		/** Gamepad face button: QTE key, L2 + face = spell slots 2-5 with the staff, or jump / dash / reload / interact. */
178		void InputFace(EGBQTEKey Key);
179		void InputJump();
180		void InputJumpReleased();
181		void InputDash();
182		void InputPrimaryPressed();
183		void InputPrimaryReleased();
184		void InputSecondaryPressed();
185		void InputSecondaryReleased();
186		void InputReload();
187		void InputSwitchWeapon(const FInputActionValue& Value);
188		void InputSpellSlot(int32 Slot);
189		void InputEnchant();
190		void InputInteract();
191		void InputQuickUse();
192		void InputCycleQuickUse(const FInputActionValue& Value);
193		void InputQTEKey(int32 KeyIndex);
194		/** Q / L2: raise / lower the summoned shield (UGBSpellbookComponent::SetBlockHeld). */
195		void InputBlockPressed();
196		void InputBlockReleased();
197		/** True while the summoned shield is raised: attacks and spells are ignored. */
198		bool IsBlocking() const;
199		/** Stops the fall after a KillZ death (movement off) and turns movement back on at respawn. */
200		void FreezeMovement();
201		void UnfreezeMovement();
202	
203		UPROPERTY(VisibleAnywhere) TObjectPtr<UCameraComponent> Camera;
204		UPROPERTY(VisibleAnywhere) TObjectPtr<USceneComponent> HeldItemAnchor;
205		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBStatsComponent> Stats;
206		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBAttributeComponent> Attributes;
207		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBStatusEffectComponent> StatusEffects;
208		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBEquipmentComponent> Equipment;
209		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBSpellbookComponent> Spellbook;
210		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBQTEComponent> QTE;
211		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBInventoryComponent> Inventory;
212		UPROPERTY(VisibleAnywhere) TObjectPtr<UGBSkillTreeComponent> SkillTree;
213	
214		/** Input actions and mapping contexts, built in code (see Player/GBInputSet.h). */
215		UPROPERTY() TObjectPtr<UGBInputSet> InputSet;
216	
217		TWeakObjectPtr<AActor> FocusedInteractable;
218	
219		bool bControlEnabled = true;
220		/** Movement turned off by a KillZ death, until RespawnAt / LoadFromSnapshot. */
221		bool bMovementFrozen = false;
222		bool bDashing = false;
223		float DashTimeLeft = 0.f;
224		double DashReadyTime = 0.0;
225		FVector DashVelocity = FVector::ZeroVector;
226		float MoveSpeedScale = 1.f;
227		/** Last movement input (x = right, y = forward), held during the QTE. */
228		FVector2D LastMoveInput = FVector2D::ZeroVector;
229		/** Frame of the last Move event outside the QTE; LastMoveInput is cleared when it gets stale. */
230		uint64 LastMoveInputFrame = 0;
231		/** Secondary (right click / L2) is held: on gamepad with the staff, L2 + face button casts slots 2-5. */
232		bool bSecondaryHeld = false;
233		/** World time of the last Precision Recovery heal (a stamp, not a timer: no reset on death). */
234		double LastPrecisionRecoveryTime = -1000000.0;
235		FDelegateHandle DamageDealtHandle;
236		FDelegateHandle DataReloadedHandle;
237		/** Recoil still to be recovered (degrees) and its recovery speed. */
238		FRotator PendingRecoil = FRotator::ZeroRotator;
239		float RecoilRecoverSpeed = 0.f;
240		/** View shake (visual only): time left / total, initial amplitude (degrees) and frequency (Hz). */
241		float ViewShakeTimeLeft = 0.f;
242		float ViewShakeDuration = 0.f;
243		float ViewShakeAmplitudeDeg = 0.f;
244		float ViewShakeFrequency = 0.f;
245	};
