143		virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;
144	
145		/** Reads the movement stats into the character movement component. Bound to OnStatsChanged. */
146		void ApplyMovementStats();
147		void HandleDeath(const FGBDamageInfo& KillingBlow);
148		/**
149		 * Precision Recovery (GDD 18): bound to UGBCombatLibrary::OnDamageDealt. When anything dies from a
150		 * weak point killing blow by this player and the perk's cooldown is over, heals the perk's fraction
151		 * of max health. Once per death by construction: only a blow that really removed health fires the event.
152		 */
153		void HandlePrecisionRecovery(AActor* Target, const FGBDamageInfo& Info, float DamageDealt);
154		void UpdateFocusedInteractable();
