179		void InputJump();
180		void InputJumpReleased();
181		void InputDash();
182		void InputPrimaryPressed();
183		void InputPrimaryReleased();
184		void InputSecondaryPressed();
185		void InputSecondaryReleased();
186		void InputReload();
187		void InputSwitchWeapon(const FInputActionValue& Value);
188		void InputSpellSlot(int32 Slot);
189		void InputEnchant();
