193		void InputQTEKey(int32 KeyIndex);
194		/** Q / L2: raise / lower the summoned shield (UGBSpellbookComponent::SetBlockHeld). */
195		void InputBlockPressed();
196		void InputBlockReleased();
197		/** True while the summoned shield is raised: attacks and spells are ignored. */
198		bool IsBlocking() const;
