const fs = require('fs');
const p = 'Design/GDD.md';
let s = fs.readFileSync(p, 'utf8');
const nl = s.includes('\r\n') ? '\r\n' : '\n';
function rep(a, b) { if (!s.includes(a)) { console.error('MISSING: ' + a.slice(0, 60)); process.exit(1); } s = s.split(a).join(b); }
rep('> Status: **v0.43, 2026-11-13** — owner\'s vision plus thirteen rounds of answers.', '> Status: **v0.44, 2026-11-13** — owner\'s vision plus fourteen rounds of answers.');
rep('## Changelog' + nl, '## Changelog' + nl + '- v0.44 (2026-11-13): owner: **the player climbs ledges**. A jump that ends at the edge of a structure climbs onto it, and pressing jump right against a block climbs it instead of jumping when one jump can reach its top. In first person the climb is the camera dipping over the edge, the held item dropping out of view and the two pixel hands gripping the ledge. Architect, provisional: the reach, durations and the "facing the wall" rule (§18 "Ledge climb"); the test arena\'s gates were re-sized for the extra reach.' + nl);
rep('| Jump | Space | Cross (A) |', '| Jump (against a reachable ledge: climb it) | Space | Cross (A) |');
const anchor = '- **Double jump on day 1:**';
rep(anchor, '- **Ledge climb (owner, 2026-11-13; details provisional, architect):** the player climbs onto a structure in two cases. (1) **In the air**, rising or falling, when the view faces a wall (within 60° of straight at it), the wall is right in front, and its top is between 15 cm and 1.6 m above the feet (the hands\' reach): the climb starts on its own. (2) **Jump pressed on the ground** right against a wall the view faces, whose top is between 0.5 m and one jump\'s rise plus the 1.6 m reach above the feet: the climb starts instead of the jump; a higher wall is a normal jump (and the double jump can still reach a climb in the air). There must be room for the player on top and above the head. The climb rises straight up, then moves forward onto the top, in 0.22 s plus 0.18 s per metre of rise; it cannot be steered and blocks attacks, spells, dash and jump while it lasts (looking stays free). Enemies are never climbed. The first-person animation: the held item (staff, sword, gun) drops out of view, both pixel hands come up from the bottom of the screen with their sleeves and grip the ledge where it is on screen, the camera pulls down a little and dips 10° (with a slight roll) as it goes over the edge, then the hands let go and the held item comes back. Numbers in `Player.json` (`Mantle*`). Side effect handled in the test arena: the reach makes things higher reachable, so the last course step now needs the double jump even with a climb, the outer walls went from 11 m to 14 m, and the arena warns if the future-only platform (6 m) could be climbed in the past.' + nl + anchor);
fs.writeFileSync(p, s);
console.log('ok');
EOF
node "$TEMP/gdd_mantle.js" && git diff --stat Design/GDD.md

