+	Camera->SetRelativeLocation(FVector(0.f, 0.f, BaseEyeHeight - Pose.Grip01 * MantlePullDownCm));
+	if (HeldItemAnchor)
+	{
+		HeldItemAnchor->SetRelativeLocation(HeldItemOffset + MantleItemLowerOffset * Pose.ItemLower01);
+	}
+}
