Add(U + 32.6f, TEXT("ui: cyber death"), [Menu](UWorld*, AGBPlayerCharacter* Player)
{
	Menu(Player, EGBMenu::None);
	FGBDamageInfo Info;
	Info.Amount = 10000000.f;
