	if (IsXRHeadTrackedCamera())
	{
		HandleXRCamera(DeltaTime);
	}

	if (bUsePawnControlRotation)
	{
		const APawn* OwningPawn = Cast<APawn>(GetOwner());
		const AController* OwningController = OwningPawn ? OwningPawn->GetController() : nullptr;
		if (OwningController && OwningController->IsLocalPlayerController())
		{
			const FRotator PawnViewRotation = OwningPawn->GetViewRotation();
			if (!PawnViewRotation.Equals(GetComponentRotation()))
			{
				SetWorldRotation(PawnViewRotation);
			}
		}
	}
	else if (TObjectPtr<ACineCameraActor> Cam = Cast<ACineCameraActor>(GetOwner()))
	{
		// TODO maybe we should do the lookat logic here instead?  Maybe with some blend amount if that can be determined.
		// Or defer the Camera tick group until the latest it can be.
		if (Cam->LookatTrackingSettings.LastLookatTrackingRotationFrame == GFrameNumber)
		{
			SetWorldRotation(Cam->LookatTrackingSettings.LastLookatTrackingRotation);
		}
	}

	if (bUseAdditiveOffset)
	{
		FTransform OffsetCamToBaseCam = AdditiveOffset;
		FTransform BaseCamToWorld = GetComponentToWorld();
		FTransform OffsetCamToWorld = OffsetCamToBaseCam * BaseCamToWorld;

		DesiredView.Location = OffsetCamToWorld.GetLocation();
		DesiredView.Rotation = OffsetCamToWorld.Rotator();
	}
	else
	{
		DesiredView.Location = GetComponentLocation();
		DesiredView.Rotation = GetComponentRotation();

codex
- **[P1] Mantle can pass through a ceiling — [GBPlayerCharacter.cpp:549](C:/GameJam/Glyphbound/Source/Glyphbound/Player/GBPlayerCharacter.cpp:549)** — Only `Mid` and `End` are checked; movement between them uses unswept teleports. With a 200 cm ledge, a thin ceiling at Z=190–198 above the starting position clears the initial capsule and both checked poses, yet the climb passes through it. **Fix:** capsule-sweep both path segments before starting, and stop safely if geometry blocks movement during the climb.

- **[P2] Unreal overwrites the mantle camera rotation — [GBPlayerCharacter.cpp:693](C:/GameJam/Glyphbound/Source/Glyphbound/Player/GBPlayerCharacter.cpp:693)** — `Camera->bUsePawnControlRotation` remains enabled. UE’s `UCameraComponent::GetCameraView` subsequently calls `SetWorldRotation(PawnViewRotation)`, removing the mantle dip, roll and composed shake from the rendered view. Looking vertically also means the camera’s relative rotation does not remain zero at rest. **Fix:** compose the visual offset after control rotation, through a camera pivot, additive camera transform or camera-view override, without changing control rotation.

- **[P2] Landing clearance does not establish landing support — [GBPlayerCharacter.cpp:546](C:/GameJam/Glyphbound/Source/Glyphbound/Player/GBPlayerCharacter.cpp:546)** — A 20 cm deep beam can supply the top hit 18 cm behind its face, while the destination centre lies 48 cm behind that face with the default capsule. Both overlap checks pass because the capsule is above the beam, but its centre is beyond the far edge; the climb finishes over an unwalkable edge and the player falls. **Fix:** validate a walkable supporting floor at the actual destination, including sufficient support for the capsule.

- **[P2] Releasing jump during a mantle can refill jumps after cancellation — [GBPlayerCharacter.cpp:602](C:/GameJam/Glyphbound/Source/Glyphbound/Player/GBPlayerCharacter.cpp:602)** — The jump count is preserved only across the initial switch to Flying. Releasing jump during the climb calls `StopJumping()`; UE’s `ResetJumpState()` clears the count while Flying. If control is then disabled and the mantle cancels into Falling, spent air jumps have been restored. **Fix:** retain the pre-mantle jump count in mantle state and restore it on cancellation; allow successful landing to reset it normally.

- **[P3] Pure tests admit visibly broken implementations — [GBPlayerTests.cpp:123](C:/GameJam/Glyphbound/Source/Glyphbound/Tests/GBPlayerTests.cpp:123)** — Returning `Grip01 = 0` throughout passes every assertion, although climbing hands never appear. A path that instantly rises after alpha zero, waits, then teleports horizontally at alpha one also passes. Reach tests use only default parameters, so hardcoded reach limits pass too. **Fix:** test interior grip values, intermediate path progress/easing, alternate rise shares, nondefault reach parameters and another jump velocity/gravity pair.

- **[P3] Smoke assertions can pass without the claimed movement — [GBDevCommands.cpp:3303](C:/GameJam/Glyphbound/Source/Glyphbound/Core/GBDevCommands.cpp:3303)** — The “normal jump” check accepts any non-ground movement mode, including Flying or None, and even accepts a grounded pawn with a stale positive jump count. The air-result check at line 3338 accepts a mantle still in progress once its height and X cross the thresholds. **Fix:** require Falling and measurable upward displacement for the normal jump; require `!IsMantling()`, Walking and platform support for the completed air grab.

Static review only; no files edited or builds/tests run.
