function rep(a,b){if(!s.includes(a)){console.error('MISSING '+a.slice(0,60));process.exit(1);}s=s.split(a).join(b);}
rep("> Status: **v0.44, 2026-11-13** — owner's vision plus fourteen rounds of answers.","> Status: **v0.45, 2026-11-13** — owner's vision plus fifteen rounds of answers.");
rep('## Changelog'+nl,'## Changelog'+nl+'- v0.45 (2026-11-13): owner: **climbing does not need the view on the wall** (\"with your back to it, for example\"). The climb now follows the player\'s intent: the held direction on the ground, the jump\'s direction in the air, and all around when there is none. When the wall is behind or beside the view, the view turns to it during the climb (architect, provisional; §18 "Ledge climb").'+nl);
rep("(1) **In the air**, rising or falling, when the view faces a wall (within 60° of straight at it), the wall is right in front,","(1) **In the air**, rising or falling, when a wall is right next to the player in the jump's direction (or anywhere around, if the jump is nearly vertical or was stopped by the wall),");
rep("(2) **Jump pressed on the ground** right against a wall the view faces,","(2) **Jump pressed on the ground** right against a wall in the held movement direction (or anywhere around when no direction is held: back to the wall works; holding a direction away from a wall behind is a normal jump),");
rep("There must be room for the player on top and above the head.","The wall must be met roughly head-on (within 60° of its face). The view no longer has to face it (owner, v0.45): if the wall is more than 60° off the view, the view turns to face it during the rise, so the player ends on top looking across it; the mouse still works during the turn. There must be room for the player on top and above the head, and floor under the landing point.");
fs.writeFileSync(p,s);console.log('ok');
EOF
node "$TEMP/gdd45.js"

